module.exports = "import React, { Component } from 'react';\nimport { PrismCode } from 'react-prism';\nimport { Player, ControlBar } from 'video-react';\nimport { Button } from 'reactstrap';\n\nconst sources = {\n  sintelTrailer: 'http://media.w3.org/2010/05/sintel/trailer.mp4',\n  bunnyTrailer: 'http://media.w3.org/2010/05/bunny/trailer.mp4',\n  bunnyMovie: 'http://media.w3.org/2010/05/bunny/movie.mp4',\n  test: 'http://media.w3.org/2010/05/video/movie_300.webm'\n};\n\nexport default class PlayerControlExample extends Component {\n  constructor(props, context) {\n    super(props, context);\n\n    this.state = {\n      source: sources.bunnyMovie\n    };\n\n    this.play = this.play.bind(this);\n    this.pause = this.pause.bind(this);\n    this.load = this.load.bind(this);\n    this.changeCurrentTime = this.changeCurrentTime.bind(this);\n    this.seek = this.seek.bind(this);\n    this.changePlaybackRateRate = this.changePlaybackRateRate.bind(this);\n    this.changeVolume = this.changeVolume.bind(this);\n    this.setMuted = this.setMuted.bind(this);\n  }\n\n  componentDidMount() {\n    // subscribe state change\n    this.player.subscribeToStateChange(this.handleStateChange.bind(this));\n  }\n\n  setMuted(muted) {\n    return () => {\n      this.player.muted = muted;\n    };\n  }\n\n  handleStateChange(state) {\n    // copy player state to this component's state\n    this.setState({\n      player: state\n    });\n  }\n\n  play() {\n    this.player.play();\n  }\n\n  pause() {\n    this.player.pause();\n  }\n\n  load() {\n    this.player.load();\n  }\n\n  changeCurrentTime(seconds) {\n    return () => {\n      const { player } = this.player.getState();\n      this.player.seek(player.currentTime + seconds);\n    };\n  }\n\n  seek(seconds) {\n    return () => {\n      this.player.seek(seconds);\n    };\n  }\n\n  changePlaybackRateRate(steps) {\n    return () => {\n      const { player } = this.player.getState();\n      this.player.playbackRate = player.playbackRate + steps;\n    };\n  }\n\n  changeVolume(steps) {\n    return () => {\n      const { player } = this.player.getState();\n      this.player.volume = player.volume + steps;\n    };\n  }\n\n  changeSource(name) {\n    return () => {\n      this.setState({\n        source: sources[name]\n      });\n      this.player.load();\n    };\n  }\n\n  render() {\n    return (\n      <div>\n        <Player\n          ref={player => {\n            this.player = player;\n          }}\n          autoPlay\n        >\n          <source src={this.state.source} />\n          <ControlBar autoHide={false} />\n        </Player>\n        <div className=\"py-3\">\n          <Button onClick={this.play} className=\"mr-3\">\n            play()\n          </Button>\n          <Button onClick={this.pause} className=\"mr-3\">\n            pause()\n          </Button>\n          <Button onClick={this.load} className=\"mr-3\">\n            load()\n          </Button>\n        </div>\n        <div className=\"pb-3\">\n          <Button onClick={this.changeCurrentTime(10)} className=\"mr-3\">\n            currentTime += 10\n          </Button>\n          <Button onClick={this.changeCurrentTime(-10)} className=\"mr-3\">\n            currentTime -= 10\n          </Button>\n          <Button onClick={this.seek(50)} className=\"mr-3\">\n            currentTime = 50\n          </Button>\n        </div>\n        <div className=\"pb-3\">\n          <Button onClick={this.changePlaybackRateRate(1)} className=\"mr-3\">\n            playbackRate++\n          </Button>\n          <Button onClick={this.changePlaybackRateRate(-1)} className=\"mr-3\">\n            playbackRate--\n          </Button>\n          <Button onClick={this.changePlaybackRateRate(0.1)} className=\"mr-3\">\n            playbackRate+=0.1\n          </Button>\n          <Button onClick={this.changePlaybackRateRate(-0.1)} className=\"mr-3\">\n            playbackRate-=0.1\n          </Button>\n        </div>\n        <div className=\"pb-3\">\n          <Button onClick={this.changeVolume(0.1)} className=\"mr-3\">\n            volume+=0.1\n          </Button>\n          <Button onClick={this.changeVolume(-0.1)} className=\"mr-3\">\n            volume-=0.1\n          </Button>\n          <Button onClick={this.setMuted(true)} className=\"mr-3\">\n            muted=true\n          </Button>\n          <Button onClick={this.setMuted(false)} className=\"mr-3\">\n            muted=false\n          </Button>\n        </div>\n        <div className=\"pb-3\">\n          <Button onClick={this.changeSource('sintelTrailer')} className=\"mr-3\">\n            Sintel teaser\n          </Button>\n          <Button onClick={this.changeSource('bunnyTrailer')} className=\"mr-3\">\n            Bunny trailer\n          </Button>\n          <Button onClick={this.changeSource('bunnyMovie')} className=\"mr-3\">\n            Bunny movie\n          </Button>\n          <Button onClick={this.changeSource('test')} className=\"mr-3\">\n            Test movie\n          </Button>\n        </div>\n        <div>State</div>\n        <pre>\n          <PrismCode className=\"language-json\">\n            {JSON.stringify(this.state.player, null, 2)}\n          </PrismCode>\n        </pre>\n      </div>\n    );\n  }\n}\n";